SELECT FIELD_NAME,FIELD_LABEL,BUSINESS_DEFINITION,DEFAULT_AGGREGATION,USAGE_NOTE FROM TUNE_BI_DB.GOLD.VW_SEMANTIC_CATALOG WHERE MART_NAME='GI_ENTERPRISE_WIDE_MART' AND FIELD_NAME IN ('GROSS_WRITTEN_PREMIUM','NET_EARNED_PREMIUM','GROSS_CLAIMS_PAID','REINSURANCE_RECOVERIES');
SELECT * FROM TUNE_BI_DB.GOLD.FIELD_DISPLAY WHERE MART_NAME IN ('GI_PLAN_MONTHLY','GI_ENTERPRISE_WIDE_MART');
SELECT COUNT(*) DUPLICATE_KEYS FROM (SELECT POLICY_NUMBER,ACCOUNTING_MONTH,COUNT(*) N FROM TUNE_BI_DB.GOLD.GI_ENTERPRISE_WIDE_MART GROUP BY ALL HAVING N>1);
SELECT COLUMN_NAME,COMMENT FROM TUNE_BI_DB.INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME='GI_PLAN_MONTHLY' AND TABLE_SCHEMA='GOLD';
SHOW GRANTS TO ROLE AGENT_ROLE;
SELECT DISTINCT DISTRIBUTION_CHANNEL FROM TUNE_BI_DB.GOLD.GI_PLAN_MONTHLY ORDER BY 1;
